package com.seminarhub.domain.seminar.service;
import com.seminarhub.domain.seminar.domain.MemberSeminarPaymentHistory; import com.seminarhub.domain.seminar.repository.MemberSeminarPaymentHistoryRepository; import com.seminarhub.global.dto.CursorRequest;
import java.util.List; import java.util.Optional; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class MemberSeminarPaymentHistoryService { private final MemberSeminarPaymentHistoryRepository repository;
@Transactional public MemberSeminarPaymentHistory save(MemberSeminarPaymentHistory e){return repository.save(e);} public Optional<MemberSeminarPaymentHistory> findById(Long id){return repository.findByIdAndDeletedAtIsNull(id);} public List<MemberSeminarPaymentHistory> findByIds(List<Long> ids){return repository.findAllByIdInAndDeletedAtIsNull(ids);} public List<MemberSeminarPaymentHistory> findAll(MemberSeminarPaymentHistorySearchQuery q){return repository.search(q);} public Page<MemberSeminarPaymentHistory> findAll(MemberSeminarPaymentHistorySearchQuery q,Pageable p){return repository.search(q,p);} public List<MemberSeminarPaymentHistory> findByCursor(MemberSeminarPaymentHistorySearchQuery q,CursorRequest c){return repository.search(q,c);} @Transactional public MemberSeminarPaymentHistory update(MemberSeminarPaymentHistory e,Long amount){e.update(amount);return e;} @Transactional public MemberSeminarPaymentHistory delete(MemberSeminarPaymentHistory e){e.delete();return e;} @Transactional public List<MemberSeminarPaymentHistory> deleteAll(List<MemberSeminarPaymentHistory> es){es.forEach(MemberSeminarPaymentHistory::delete);return es;} }
